    Generate an MCP server from an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a dict
        http_client: Configured httpx.AsyncClient with base URL

    Returns:
        A fastmcp Server with tools for each OpenAPI operation
    """
    server = Server("openapi-mcp-server")

    paths = openapi_spec.get("paths", {})

    for path, path_item in paths.items():
        for method, operation in path_item.items():
            if method.upper() not in ("GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"):
                continue

            if not isinstance(operation, dict):
                continue

            operation_id = operation.get("operationId", f"{method.upper()}_{path.replace('/', '_').strip('_')}")
            summary = operation.get("summary", "")
            description = operation.get("description", "")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            tool_input_schema = {
                "type": "object",
                "properties": {},
                "required": [],
            }

            for param in parameters:
                param_name = param.get("name")
                param_schema = param.get("schema", {})
                param_type = param_schema.get("type", "string")

                tool_input_schema["properties"][param_name] = {
                    "type": param_type,
                    "description": param.get("description", ""),
                }

