                        param_name = param.get("name")
                        param_in = param.get("in")

                        if param_name in kwargs:
                            value = kwargs[param_name]
                            if param_in == "query":
                                query_params[param_name] = value
                            elif param_in == "path":
                                url = url.replace(f"{{{param_name}}}", str(value))
                            elif param_in == "header":
