                        response = await http_client.request(
                            op_method.upper(),
                            url,
                            params=query_params or None,
                            json=body_data,
                            headers=headers or None,
                        )
                        return response.text
                    except Exception as e:
                        return f"Error: {str(e)}"

                return handler

